# bot/data/admin_translations.py
"""Admin panel translations.

Maps the English admin-panel UI strings to per-language translations.
The admin panel is large, so translations are keyed by the exact English
source string and looked up at render time via ``admin_str()``. Strings
without a translation fall back to English automatically.
"""

ADMIN_TRANSLATIONS = {}

def _add(en, ur, ar, hi, bn, id, es, ru, zh_cn, zh_tw, ja, ko, my):
    ADMIN_TRANSLATIONS[en] = {
        "en": en,
        "ur": ur,
        "ar": ar,
        "hi": hi,
        "bn": bn,
        "id": id,
        "es": es,
        "ru": ru,
        "zh_cn": zh_cn,
        "zh_tw": zh_tw,
        "ja": ja,
        "ko": ko,
        "my": my,
    }

